    const byType = {};
    realRacks.forEach((r) => { const k = r.rackType || "Unassigned"; byType[k] = (byType[k] || 0) + 1; });
    heading("RACK TYPE COLOURS");
    const typeNames = Object.keys(byType).sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
    if (!typeNames.length)
        row(sw([241, 245, 249], [203, 213, 225]), "No racks", "");
    typeNames.slice(0, 22).forEach((t) => {
        const c = t === "Unassigned" ? "#94A3B8" : rackTypeColor(t);
        row((x, y) => { doc.setFillColor(...fpdfMix(c, 0.6)); doc.rect(x, y, 7, 3.6, "F"); doc.setFillColor(...fpdfRgb(c)); doc.rect(x, y, 7, 1.1, "F"); doc.setDrawColor(...fpdfRgb(c)); doc.setLineWidth(0.3); doc.rect(x, y, 7, 3.6, "S"); }, t, byType[t]);
    });
    if (typeNames.length > 22) {
        doc.setFontSize(7);
        doc.setTextColor(100, 116, 139);
        doc.text(`+ ${typeNames.length - 22} more types`, lx + 15, cy);
        cy += 5;
    }
    cy += 2;
    heading("FLOOR ELEMENTS");
    row((x, y) => { doc.setDrawColor(0, 0, 0); doc.setLineWidth(0.9); doc.line(x, y + 1.8, x + 7, y + 1.8); }, "Boundary line");
    row((x, y) => { doc.setLineCap("round"); doc.setDrawColor(5, 150, 105); doc.setLineWidth(1.4); doc.line(x, y + 1.8, x + 7, y + 1.8); doc.setLineCap("butt"); }, "Entry");
    row((x, y) => { doc.setLineCap("round"); doc.setDrawColor(217, 119, 6); doc.setLineWidth(1.4); doc.line(x, y + 1.8, x + 7, y + 1.8); doc.setLineCap("butt"); }, "Exit");
