    row((x, y) => { doc.setFillColor(248, 250, 252); doc.rect(x, y, 7, 3.6, "F"); doc.setDrawColor(148, 163, 184); doc.setLineWidth(0.3); doc.setLineDashPattern([0.9, 0.7], 0); doc.rect(x, y, 7, 3.6, "S"); doc.setLineDashPattern([], 0); }, "Empty space");
    row(sw([224, 242, 254], [14, 165, 233], true), "Cold aisle");
    row(sw([254, 226, 226], [239, 68, 68], true), "Hot aisle");
    row(sw([254, 243, 199], [245, 158, 11]), "Electrical (MCP / PDU)");
    row((x, y) => { doc.setDrawColor(124, 58, 237); doc.setLineWidth(0.7); doc.rect(x, y, 7, 3.6, "S"); }, "Cage");
