    const allSites = [...new Set([...(allowedSites || []), ...activeAssets.map(a => a.site), ...issues.map(i => i.site), ...activities.map(a => a.site), ...(movements || []).map(m => m.site), ...(zones || []).map(z => z.site)].filter(Boolean))].sort();
