            const allRacks = buildRacks(zoneAssets, zonePlanned).filter((r) => !r.structural); // pillars / empty-space blocks are not capacity racks (same as DC Capacity)
            const usedRackNos = new Set(zoneAssets.filter(a => a.rackNo).map(a => String(a.rackNo).trim().toUpperCase()));
            const totalR = allRacks.length;
